// Room "P1 north-east bedroom" (interior designer's part): one bed with its head on the east wall (x29 is solid at z14),
// a barrel nightstand with a lit candle, a chest dresser on the north-west corner, a potted flower by the west door,
// and one hanging lantern over the middle. The door lane (x26..28, z15) and the two cells over the bed stay clear.
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // the bed: foot at (27,6,14), head at (28,6,14) against the east wall (pillow end toward +x)
  bed(g, [27, 6, 14], "east", "red");

  // floor layer (feet y6): chest dresser, nightstand barrel, potted flower
  layers(g, [26, 6, 14], {
    "c": ["chest", { facing: "south" }],
    "r": "barrel",
    "p": "potted_poppy",
  }, [
    ["c..",   // z14: chest at (26,14); the bed is placed above by bed()
     "..r",   // z15: nightstand barrel at (28,15), beside the bed head
     "..p"],  // z16: potted poppy at (28,16)
  ]);

  // the candle on the nightstand, at feet+1 (y7), and the hanging lantern under the ceiling block (y8)
  layers(g, [26, 7, 14], {
    "k": ["candle", { candles: "2", lit: "true" }],
  }, [
    ["...",
     "..k",
     "..."],
  ]);
  layers(g, [26, 8, 14], {
    "l": ["lantern", { hanging: "true" }],
  }, [
    ["...",
     ".l.",
     "..."],
  ]);
}

